// Render merge fields. Anything the DB could not verify gets a graceful fallback —
// a template that ships "Hi {{first_name}}" literally is worse than no email at all,
// so a row that would render a visible placeholder is DROPPED, not sent.
const SENDER_PHONE = '+880 1322 840799';
const out = [];

for (const item of $input.all()) {
  const d = item.json;

  const person = (d.owner_name || d.manager_name || '').trim();
  const firstName = person ? person.split(/\s+/)[0] : '';

  const fill = (tpl) => String(tpl || '')
    .replaceAll('{{first_name}}', firstName || 'there')
    .replaceAll('{{hotel_name}}', d.hotel_name || 'your hotel')
    .replaceAll('{{city}}', d.city || 'Bangladesh')
    .replaceAll('{{rooms}}', d.rooms ? String(d.rooms) : 'your')
    .replaceAll('{{sender_phone}}', SENDER_PHONE);

  const subject = fill(d.subject_template);
  const body = fill(d.body_template);

  // Safety net: never let an unresolved placeholder reach a prospect.
  if (/\{\{|\}\}/.test(subject + body)) continue;

  // When rooms is unknown the step-2 sentence reads badly — swap it for the generic form.
  const cleanBody = d.rooms
    ? body
    : body.replace('A your-room property has the same problems we did, just at a different scale.',
                   'A property your size has the same problems we did.');

  out.push({ json: { ...d, first_name: firstName, subject, body: cleanBody } });
}

return out;
